"""Format metadata for docs/ and manifest.json. Edit this file, then run `python3 -I scripts/build_docs.py`.

Conventions
- status: DONE = baseline (or the documented substitute) exists and is verified; PARTIAL = baseline exists, listed
  variants outstanding; BLOCKED = cannot be made now (see blocked); TODO = not started; SKIP / WONTDO as in Confluence.
  The status tracks fixture work only. It says nothing about MacPacker support.
- mime / uti are reference values (IANA, shared-mime-info, Apple docs) that were NOT checked by this work unless
  marked "(verified)". magic is the signature seen at the given offset in the fixtures (verified by hexdump).
- fixtures: glob patterns relative to the repo root.
"""

STD = "standard"  # defaultArchiveContent: hello world.txt, folder/README.md, folder/NestedArchive.zip

